```tsx
import { useId } from "react";
import type { ReactElement } from "react";
import "./ChecklistItem.css";

export interface ChecklistItemProps {
  title: string;
  detail: string;
  minutes: number;
  done: boolean;
  onToggle: () => void;
}

export function ChecklistItem({
  title,
  detail,
  minutes,
  done,
  onToggle,
}: ChecklistItemProps): ReactElement {
  const titleId = useId();
  const detailId = useId();

  return (
    <div className={done ? "checklist-item is-done" : "checklist-item"}>
      <button
        type="button"
        className="checklist-check"
        aria-pressed={done}
        aria-labelledby={titleId}
        aria-describedby={detailId}
        onClick={onToggle}
      >
        <span className="checklist-tick" aria-hidden="true" />
      </button>
      <div className="checklist-text">
        <span id={titleId} className="checklist-title">
          {title}
        </span>
        <span id={detailId} className="checklist-detail">
          {detail}
        </span>
      </div>
      <span className="checklist-minutes">{minutes} min</span>
    </div>
  );
}
```

