.checklist-item {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(0.75rem, 2vw, 1rem);
  padding: clamp(0.75rem, 1.6vw, 1rem) 0;
  border-bottom: 1px solid var(--hair);
  color: var(--ink);
}

.checklist-check {
  font: inherit;
  display: grid;
  place-items: center;
  flex: none;
  inline-size: clamp(1.75rem, 3vw, 2.125rem);
  aspect-ratio: 1;
  padding: 0;
  border-radius: 999px;
  border: 2px solid var(--muted);
  background: transparent;
  color: var(--ink);
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease;
}

.checklist-check:hover {
  border-color: var(--ink);
}

.checklist-tick {
  display: none;
  inline-size: 40%;
  block-size: 20%;
  border-left: 3px solid currentColor;
  border-bottom: 3px solid currentColor;
  transform: translateY(-15%) rotate(-45deg);
}

.checklist-item.is-done .checklist-check {
  background: var(--myelin);
  border-color: var(--myelin);
  color: var(--slide);
}

.checklist-item.is-done .checklist-tick {
  display: block;
}

.checklist-text {
  display: grid;
  gap: 0.125rem;
  min-inline-size: 0;
}

.checklist-title {
  font-size: clamp(1rem, 1.6vw, 1.15rem);
  color: var(--ink);
  overflow-wrap: anywhere;
}

.checklist-item.is-done .checklist-title {
  color: var(--muted);
  text-decoration: line-through;
}

.checklist-detail {
  font-size: clamp(0.85rem, 1.3vw, 0.95rem);
  color: var(--muted);
}

.checklist-minutes {
  font-size: clamp(0.85rem, 1.3vw, 0.95rem);
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

:root[data-motion="reduce"] .checklist-check {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .checklist-check {
    transition: none;
  }
}
